/* Local, keyboard-operable dropdowns and date/time pickers. No browser popup UI. */
(function(){'use strict';
const entries=new Map(),pad=n=>String(n).padStart(2,'0');
let popup=null,opener=null,activeInput=null;
const months=['Gennaio','Febbraio','Marzo','Aprile','Maggio','Giugno','Luglio','Agosto','Settembre','Ottobre','Novembre','Dicembre'];
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function button(text,cls,fn){const b=el('button',cls,text);b.type='button';if(fn)b.addEventListener('click',fn);return b;}
function fieldLabel(input){const label=input.closest('label');return input.getAttribute('aria-label')||(label?[...label.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent.trim()).join(' '):'Seleziona');}
function formatted(input){if(input.tagName==='SELECT')return input.selectedOptions[0]?.textContent||'Seleziona';const val=input.value;if(!val)return 'Seleziona';if(input.type==='time')return val;const [d,t]=val.split('T'),[y,m,day]=d.split('-');return `${day} ${months[Number(m)-1].toLowerCase()} ${y}`+(t?' \u00b7 '+t:'');}
function refresh(){for(const [input,b]of entries){b.querySelector('.custom-value').textContent=formatted(input);b.disabled=input.disabled;b.setAttribute('aria-label',fieldLabel(input)+': '+formatted(input));}}
function addValue(input,value){if(input.tagName==='SELECT'&&![...input.options].some(o=>o.value===String(value))){const opt=new Option(value+' '+(input.dataset.customUnit||''),String(value));input.add(opt);}input.value=String(value);refresh();}
function setValue(input,val){addValue(input,val);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}
function close(){if(!popup)return;popup.close();}
function makePopup(input,kind){
 if(popup)popup.close();activeInput=input;opener=entries.get(input);opener.setAttribute('aria-expanded','true');
 const d=el('dialog','control-popup '+kind);popup=d;d.setAttribute('aria-label',fieldLabel(input));
 const head=el('div','control-head');head.append(el('span','section-label',fieldLabel(input)),button('\u00d7','control-close',close));head.lastChild.innerHTML=window.IstanteIcons.render('close');head.lastChild.setAttribute('aria-label','Chiudi selettore');d.append(head);
 d.addEventListener('close',()=>{const b=opener;if(b)b.setAttribute('aria-expanded','false');d.remove();if(popup===d){popup=null;activeInput=null;}if(b?.isConnected)b.focus({preventScroll:true});});
 d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();d.close();}});
 document.body.append(d);return d;
}
function openSelect(input){
 const d=makePopup(input,'select-popup'),list=el('div','custom-options');list.setAttribute('role','listbox');list.setAttribute('aria-label',fieldLabel(input));let opts=[],search=null;
 if(input.dataset.search==='true'||input.options.length>12){
  search=el('input','select-search');search.type='search';search.placeholder='Cerca una stazione...';search.setAttribute('aria-label','Cerca nel catalogo');search.autocomplete='off';d.append(search);
 }
 for(const o of input.options){const b=button(o.textContent,'custom-option',()=>{setValue(input,o.value);close();});b.setAttribute('role','option');b.setAttribute('aria-selected',String(o.selected));b.disabled=o.disabled;list.append(b);opts.push(b);}
 const available=()=>opts.filter(b=>!b.hidden&&!b.disabled);
 list.addEventListener('keydown',e=>{const a=available();if(!a.length)return;let i=a.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();i=e.key==='Home'?0:e.key==='End'?a.length-1:(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length;a[i].focus();}else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){const target=a.find((b,j)=>j>i&&b.textContent.replace(/^\d+\s+/,'').toLowerCase().startsWith(e.key.toLowerCase()))||a.find(b=>b.textContent.replace(/^\d+\s+/,'').toLowerCase().startsWith(e.key.toLowerCase()));target?.focus();}});
 d.append(list);const empty=el('p','select-empty','Nessuna stazione trovata.');empty.hidden=true;d.append(empty);
 if(search){search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase('it');for(const b of opts)b.hidden=!b.textContent.toLocaleLowerCase('it').includes(q);empty.hidden=available().length>0;});search.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();available()[0]?.focus();}else if(e.key==='Enter'){e.preventDefault();if(available().length===1)available()[0].click();}});}
 if(input.dataset.customUnit){const section=el('div','custom-number'),label=el('label',null,'Oppure imposta '+input.dataset.customUnit),n=el('input');n.type='number';n.min=input.dataset.customMin;n.max=input.dataset.customMax;n.step='1';n.inputMode='numeric';n.value=Number(input.value)>0?input.value:n.min;label.append(n);const error=el('p','form-error');error.setAttribute('role','alert');const apply=()=>{const v=Number(n.value);if(!n.value||!Number.isInteger(v)||v<+n.min||v>+n.max){error.textContent='Inserisci un valore da '+n.min+' a '+n.max+'.';return;}setValue(input,String(v));close();};section.append(label,button('Applica','secondary-button',apply),error);n.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();apply();}});d.append(section);}

 d.showModal();const selected=opts.find(b=>b.getAttribute('aria-selected')==='true')||opts[0];
 (search||selected)?.focus({preventScroll:true});if(!search)selected?.scrollIntoView({block:'nearest'});
}
function openDate(input){
 const isTime=input.type==='time',hasTime=input.type==='datetime-local'||isTime,d=makePopup(input,'date-popup');
 const val=input.value;let chosen=isTime?new Date():new Date(val||Date.now());if(!Number.isFinite(+chosen))chosen=new Date();
 let hour=isTime?Number((val||'12:00').slice(0,2)):chosen.getHours(),minute=isTime?Number((val||'12:00').slice(3,5)):chosen.getMinutes();let month=chosen.getMonth(),year=chosen.getFullYear();
 const datePart=el('div','date-part'),calendar=el('div','calendar-grid');calendar.setAttribute('role','grid');calendar.setAttribute('aria-label','Scegli il giorno');
 function draw(){datePart.replaceChildren();const nav=el('div','calendar-nav');const back=button('\u2039','calendar-arrow',()=>{if(month===0){year--;month=11;}else month--;draw();});back.innerHTML=window.IstanteIcons.render('left');back.setAttribute('aria-label','Mese precedente');const next=button('\u203a','calendar-arrow',()=>{if(month===11){year++;month=0;}else month++;draw();});next.innerHTML=window.IstanteIcons.render('right');next.setAttribute('aria-label','Mese successivo');
 const title=button(months[month]+' '+year,'calendar-month',()=>{monthMenu.hidden=!monthMenu.hidden;});title.setAttribute('aria-label','Scegli mese e anno');
 nav.append(back,title,next);datePart.append(nav);const monthMenu=el('div','month-menu');monthMenu.hidden=true;const yr=el('label',null,'Anno'),yn=el('input');yn.type='number';yn.min='1900';yn.max='2200';yn.value=year;yn.setAttribute('aria-label','Anno');yn.addEventListener('change',()=>{if(+yn.value>=1900&&+yn.value<=2200)year=+yn.value;});yr.append(yn);monthMenu.append(yr);months.forEach((m,i)=>monthMenu.append(button(m.slice(0,3),'month-choice',()=>{month=i;draw();})));datePart.append(monthMenu);
 const weekdays=el('div','calendar-weekdays');['L','M','M','G','V','S','D'].forEach(t=>weekdays.append(el('span',null,t)));datePart.append(weekdays);calendar.replaceChildren();
 const offset=(new Date(year,month,1).getDay()+6)%7,total=new Date(year,month+1,0).getDate();for(let i=0;i<offset;i++)calendar.append(el('span','calendar-blank'));
 for(let day=1;day<=total;day++){const date=new Date(year,month,day),selected=chosen.getFullYear()===year&&chosen.getMonth()===month&&chosen.getDate()===day;const b=button(String(day),'calendar-day',()=>{chosen=new Date(year,month,day);draw();calendar.querySelector('[aria-selected=true]')?.focus({preventScroll:true});});b.dataset.day=day;b.setAttribute('role','gridcell');b.setAttribute('aria-selected',String(selected));b.setAttribute('aria-label',`${day} ${months[month]} ${year}`);b.tabIndex=selected?0:-1;if(date.toDateString()===new Date().toDateString())b.setAttribute('aria-current','date');calendar.append(b);}
 if(!calendar.querySelector('[tabindex="0"]'))calendar.querySelector('button').tabIndex=0;
 datePart.append(calendar);}
 calendar.addEventListener('keydown',e=>{const deltas={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(Object.hasOwn(deltas,e.key)&&e.target.dataset.day){e.preventDefault();const target=new Date(year,month,+e.target.dataset.day+deltas[e.key]);chosen=target;month=target.getMonth();year=target.getFullYear();draw();calendar.querySelector('[aria-selected=true]')?.focus();}});
 if(!isTime){draw();d.append(datePart);}
 if(hasTime){const timePart=el('div','time-part');const note=el('p','field-note','Scegli ore e minuti');timePart.append(note);const cols=el('div','time-columns');
 for(const [type,total]of [['Ore',24],['Minuti',60]]){const col=el('div','time-column-wrap'),label=el('span','section-label',type),list=el('div','time-column');list.setAttribute('role','listbox');list.setAttribute('aria-label',type);for(let i=0;i<total;i++){const b=button(pad(i),'time-option',()=>{if(type==='Ore')hour=i;else minute=i;[...list.children].forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1;});});b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===(type==='Ore'?hour:minute)));b.tabIndex=i===(type==='Ore'?hour:minute)?0:-1;list.append(b);}
 list.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const a=[...list.children],i=a.indexOf(document.activeElement),j=e.key==='Home'?0:e.key==='End'?a.length-1:(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length;a[j].focus();a[j].click();}});col.append(label,list);cols.append(col);}timePart.append(cols);d.append(timePart);}
 const manual=el('details','manual-picker'),summary=el('summary',null,'Oppure scrivi '+(isTime?'l\u2019ora':'data e ora')),manualField=el('input');manualField.type='text';manualField.placeholder=isTime?'HH:MM':'GG/MM/AAAA HH:MM';manualField.setAttribute('aria-label',manualField.placeholder);manual.append(summary,manualField);d.append(manual);
 const error=el('p','form-error');error.setAttribute('role','alert');d.append(error);const foot=el('div','control-footer');
 const apply=()=>{if(manual.open&&manualField.value.trim()){const raw=manualField.value.trim(),m=raw.match(isTime?/^(\d{1,2}):(\d{2})$/:/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?$/);if(!m){error.textContent='Formato non valido: '+manualField.placeholder+'.';return;}if(isTime){hour=+m[1];minute=+m[2];}else{const candidate=new Date(+m[3],+m[2]-1,+m[1]);if(candidate.getDate()!==+m[1]||candidate.getMonth()!==+m[2]-1||+m[3]<1900||+m[3]>2200){error.textContent='Questa data non esiste.';return;}chosen=candidate;hour=m[4]===undefined?hour:+m[4];minute=m[5]===undefined?minute:+m[5];}}if(hour<0||hour>23||minute<0||minute>59){error.textContent='Usa ore da 00 a 23 e minuti da 00 a 59.';return;}const time=pad(hour)+':'+pad(minute),date=chosen.getFullYear()+'-'+pad(chosen.getMonth()+1)+'-'+pad(chosen.getDate());setValue(input,isTime?time:date+(hasTime?'T'+time:''));close();};
 foot.append(button('Annulla','text-button',close),button('Conferma','primary-button',apply));d.append(foot);d.showModal();d.querySelectorAll('.time-column [aria-selected=true]').forEach(b=>b.scrollIntoView({block:'center'}));d.querySelector('.calendar-day[aria-selected=true],.time-option[aria-selected=true],.calendar-day')?.focus({preventScroll:true});
}
function enhance(root){root.querySelectorAll('select,input[type="time"],input[type="date"],input[type="datetime-local"]').forEach(input=>{if(entries.has(input))return;const b=button('','custom-trigger',()=>input.tagName==='SELECT'?openSelect(input):openDate(input));b.setAttribute('aria-haspopup',input.tagName==='SELECT'?'listbox':'dialog');b.setAttribute('aria-expanded','false');b.append(el('span','custom-value'),el('span','custom-chevron','\u2304'));b.lastChild.innerHTML=window.IstanteIcons.render(input.tagName==='SELECT'?'chevron':input.type==='time'?'clock':'calendar');input.hidden=true;input.tabIndex=-1;input.after(b);entries.set(input,b);input.addEventListener('change',refresh);b.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();b.click();}});});refresh();}
window.IstanteControls={enhance,refresh,addValue};
})();
